CREATE TABLE IF NOT EXISTS users (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,phone VARCHAR(20) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,role ENUM('customer','admin') NOT NULL DEFAULT 'customer',active BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS products (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(180) NOT NULL,slug VARCHAR(190) NOT NULL UNIQUE,description TEXT,long_description MEDIUMTEXT,image_path VARCHAR(255),brand VARCHAR(100) NOT NULL DEFAULT 'bilumiere',category ENUM('women','men','unisex','niche') NOT NULL,active BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX(category,active),INDEX(brand,active)
) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS product_variants (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,product_id BIGINT UNSIGNED NOT NULL,sku VARCHAR(80) NOT NULL UNIQUE,color VARCHAR(50) NOT NULL,size VARCHAR(30),price BIGINT UNSIGNED NOT NULL,stock INT UNSIGNED NOT NULL DEFAULT 0,low_stock_threshold INT UNSIGNED NOT NULL DEFAULT 4,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE CASCADE,INDEX(product_id,stock)
) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS orders (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,order_number VARCHAR(40) NOT NULL UNIQUE,user_id BIGINT UNSIGNED NOT NULL,status ENUM('pending','confirmed','processing','sent','delivered','cancelled') NOT NULL DEFAULT 'pending',payment_status ENUM('unpaid','paid','failed','refunded') NOT NULL DEFAULT 'unpaid',subtotal BIGINT UNSIGNED NOT NULL,shipping BIGINT UNSIGNED NOT NULL DEFAULT 0,discount BIGINT UNSIGNED NOT NULL DEFAULT 0,coupon_code VARCHAR(40),total BIGINT UNSIGNED NOT NULL,shipping_address JSON NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id),INDEX(user_id,created_at),INDEX(status,created_at)
) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS order_items (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,order_id BIGINT UNSIGNED NOT NULL,product_id BIGINT UNSIGNED NOT NULL,variant_id BIGINT UNSIGNED NOT NULL,sku VARCHAR(80) NOT NULL,unit_price BIGINT UNSIGNED NOT NULL,quantity INT UNSIGNED NOT NULL,FOREIGN KEY(order_id) REFERENCES orders(id) ON DELETE CASCADE,FOREIGN KEY(product_id) REFERENCES products(id),FOREIGN KEY(variant_id) REFERENCES product_variants(id)
) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS payments (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,order_id BIGINT UNSIGNED NOT NULL,authority VARCHAR(120) NOT NULL UNIQUE,amount BIGINT UNSIGNED NOT NULL,status ENUM('pending','paid','failed','refunded') NOT NULL,reference_id VARCHAR(120),paid_at DATETIME,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(order_id) REFERENCES orders(id),INDEX(order_id,status)
) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS inventory_movements (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,variant_id BIGINT UNSIGNED NOT NULL,order_id BIGINT UNSIGNED,quantity INT NOT NULL,type ENUM('sale','return','adjustment','restock') NOT NULL,note VARCHAR(255),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(variant_id) REFERENCES product_variants(id),FOREIGN KEY(order_id) REFERENCES orders(id),INDEX(variant_id,created_at)
) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS audit_logs (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED,action VARCHAR(100) NOT NULL,entity_type VARCHAR(60),entity_id BIGINT UNSIGNED,metadata JSON,ip_address VARCHAR(45),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL,INDEX(action,created_at)
) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS product_images (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,product_id BIGINT UNSIGNED NOT NULL,path VARCHAR(255) NOT NULL,sort_order INT NOT NULL DEFAULT 0,FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE CASCADE,INDEX(product_id,sort_order)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS favorites (user_id BIGINT UNSIGNED NOT NULL,product_id BIGINT UNSIGNED NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(user_id,product_id),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS reviews (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,product_id BIGINT UNSIGNED NOT NULL,rating TINYINT UNSIGNED NOT NULL,body TEXT NOT NULL,approved BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY(user_id,product_id),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE CASCADE,INDEX(product_id,approved)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS addresses (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,title VARCHAR(80) NOT NULL,recipient VARCHAR(120) NOT NULL,phone VARCHAR(20) NOT NULL,province VARCHAR(80) NOT NULL,city VARCHAR(80) NOT NULL,address TEXT NOT NULL,postal_code VARCHAR(10) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,INDEX(user_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS coupons (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,code VARCHAR(40) NOT NULL UNIQUE,type ENUM('percent','fixed') NOT NULL,value BIGINT UNSIGNED NOT NULL,min_order BIGINT UNSIGNED NOT NULL DEFAULT 0,active BOOLEAN NOT NULL DEFAULT TRUE,expires_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS settings (`key` VARCHAR(80) PRIMARY KEY,`value` TEXT NOT NULL,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB;
